export const TYPES=['企業','概念','業務／服務','產品／技術','敘述','公式','實例'];
export const RELATIONS=['拆解／組成','先備知識','提供產品或服務','使用技術','應用','類比／相關','供應','客戶','合作','競爭','股權隸屬'];
export const MODEL_NAMES={Fabless:'Fabless（無晶圓廠 IC 設計）',Foundry:'Foundry（晶圓代工）',IDM:'IDM（整合元件製造）',OSAT:'OSAT（委外封裝與測試）',EMS:'EMS（電子製造服務）'};
export const clone=x=>JSON.parse(JSON.stringify(x));
export function dimensions(){return [
['abstract','抽象程度',['具體企業、產品或案例。','從具體對象歸納出一項可辨識的功能或作法。','解釋業務的概念或商業模式。','整合多種概念，可解釋不同產業環節的共同機制。','可跨情境使用的一般產業原理。']],
['prerequisite','先備知識門檻',['用日常語言即可理解。','只需一項基本術語，經簡短說明即可理解。','需要數個半導體基本概念。','需結合一個環節的多項技術與營運概念。','需要串連多項技術、營運或供應鏈知識。']],
['industry','半導體產業相關程度',['較遠的延伸，與產業分工僅間接相關。','可作為輔助例子，移除後仍不影響產業理解。','理解半導體產業的重要背景。','直接支持理解一個主要環節或關鍵連結。','理解產業分工或企業定位的核心內容。']],
['transfer','跨領域通用程度',['主要適用於特定企業、產品或案例。','可用於同類產品或相同環節的其他案例。','適用於數個相關產業環節。','可從半導體延伸到另一產業，需調整術語與條件。','可用於不同產業或多種商業情境。']],
['position','企業定位解釋力',['主要補充背景，無法單獨說明企業角色。','協助辨識某項技術或需求，但仍需其他概念連接業務。','能解釋某一部分業務。','能連接企業的活動、交付物與客戶需求。','能直接說明企業提供的價值、分工或差異。']]
].map(([id,name,rules])=>({id,name,min:1,max:5,rules:Object.fromEntries(rules.map((x,i)=>[i+1,x])),kind:'編輯判斷',editable:true}));}
export function groups(nodes,x,y){const m=new Map();for(const n of nodes){const a=n.scores?.[x]?.value,b=n.scores?.[y]?.value;if(!Number.isInteger(a)||!Number.isInteger(b))continue;const k=`${a},${b}`;if(!m.has(k))m.set(k,{key:k,x:a,y:b,nodes:[]});m.get(k).nodes.push(n);}return [...m.values()];}
export function pendingNodes(data){return data.nodes.filter(n=>data.dimensions.some(d=>!Number.isInteger(n.scores?.[d.id]?.value)));}
export function neighborhood(data,id){const ids=new Set([id]);data.relations.forEach(r=>{if(r.source===id)ids.add(r.target);if(r.target===id)ids.add(r.source)});return ids;}
export function companyScope(data,id){const ids=neighborhood(data,id);const n=data.nodes.find(x=>x.id===id);n?.answers?.forEach(a=>a.refs?.forEach(ref=>ids.add(ref)));return ids;}
export function filterNodes(data,{search='',type='',role='',company='',mode='knowledge'}={}){const scope=company?companyScope(data,company):null;const q=search.toLowerCase().trim();return data.nodes.filter(n=>(mode!=='company'||n.type==='企業')&&(!type||n.type===type)&&(!role||n.classification?.activities?.some(a=>a.label===role))&&(!scope||scope.has(n.id))&&(!q||[n.title,n.definition,n.formalName,n.englishName,...(n.aliases||[]),...(n.tags||[]),...(n.classification?.models||[]),...(n.classification?.domains||[]),...(n.classification?.applications||[])].join(' ').toLowerCase().includes(q)));}
export function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
export function validate(data){const errors=[];if(!data||typeof data!=='object'||!Array.isArray(data.nodes)||!Array.isArray(data.relations)||!Array.isArray(data.dimensions))return ['需要包含 nodes、relations、dimensions 陣列的完整 JSON。'];if(data.schemaVersion!==1)errors.push('不支援的 schemaVersion；第一版須為 1。');const ns=new Set(),ds=new Set(),rs=new Set();for(const d of data.dimensions){if(!d||typeof d.id!=='string'||!d.id||ds.has(d.id))errors.push('維度 ID 缺漏或重複。');ds.add(d?.id);if(!d?.name||typeof d.name!=='string')errors.push('維度名稱不可空白。');if(d?.min!==1||d?.max!==5)errors.push('目前維度範圍須為 1–5。');for(let i=1;i<=5;i++)if(typeof d?.rules?.[i]!=='string'||!d.rules[i].trim())errors.push(`${d?.name||'維度'}缺少 ${i} 分判準。`);}if(!data.dimensions.length)errors.push('至少需要兩個維度。');if(data.dimensions.length<2)errors.push('座標圖需要兩個不同維度。');function sourceCheck(src,label){if(!Array.isArray(src)){errors.push(`${label}的 sources 必須為陣列。`);return}for(const s of src)if(typeof s?.title!=='string'||!safeUrl(s?.url)||typeof s?.checkedAt!=='string'||typeof s?.publishedAt!=='string'||typeof s?.period!=='string')errors.push(`${label}來源需要標題、http(s) 網址、發布日期、適用期間與查核日期。`);}
for(const n of data.nodes){if(!n||typeof n.id!=='string'||!n.id.trim()||ns.has(n.id))errors.push('節點 ID 缺漏或重複。');ns.add(n?.id);if(!n?.title||typeof n.title!=='string'||!TYPES.includes(n.type)||typeof n.definition!=='string'||!n.definition.trim()||typeof n.detail!=='string')errors.push(`${n?.id||'節點'}缺少有效標題、類型、定義或內容。`);if(!['已查證事實','分析性解釋','待查證內容'].includes(n?.status))errors.push(`${n?.title}的查證狀態無效。`);const c=n?.classification;if(!c||!Array.isArray(c.activities)||!['models','domains','applications'].every(k=>Array.isArray(c[k])&&c[k].every(v=>typeof v==='string'))||c.activities.some(a=>!a||typeof a.label!=='string'||!['主要','其他'].includes(a.priority)))errors.push(`${n?.title}的分類格式無效。`);for(const k of ['tags','aliases'])if(n[k]!=null&&(!Array.isArray(n[k])||n[k].some(x=>typeof x!=='string')))errors.push(`${n?.title}的 ${k} 格式無效。`);if(!n.scores||typeof n.scores!=='object')errors.push(`${n?.title}缺少 scores 物件（可為空）。`);for(const [key,s] of Object.entries(n?.scores||{})){if(!ds.has(key))errors.push(`${n.title}有未知評分維度 ${key}。`);if(!s||typeof s!=='object'){errors.push(`${n.title}評分格式無效。`);continue}if(s.value!=null&&(!Number.isInteger(s.value)||s.value<1||s.value>5))errors.push(`${n.title}評分必須為 1–5 的整數或 null。`);if(s.value!=null&&(typeof s.reason!=='string'||!s.reason.trim()))errors.push(`${n.title}每個分數都需要理由。`);}sourceCheck(n?.sources,n?.title);if(n.answers!=null&&(!Array.isArray(n.answers)||n.answers.some(a=>!a||typeof a.question!=='string'||typeof a.text!=='string'||!Array.isArray(a.refs)||a.refs.some(r=>typeof r!=='string'))))errors.push(`${n.title}企業問答格式無效。`);}
for(const n of data.nodes){if(Array.isArray(n.answers))for(const a of n.answers)if(Array.isArray(a?.refs))for(const id of a.refs)if(!ns.has(id))errors.push(`${n.title}問答引用未知節點 ${id}。`)}
for(const r of data.relations){if(!r||typeof r.id!=='string'||rs.has(r.id))errors.push('關係 ID 缺漏或重複。');rs.add(r?.id);if(!ns.has(r?.source)||!ns.has(r?.target))errors.push(`關係 ${r?.id} 的端點不存在。`);if(r?.source===r?.target)errors.push(`關係 ${r?.id} 不可連到自己。`);if(!RELATIONS.includes(r?.type))errors.push(`關係 ${r?.id} 類型無效。`);sourceCheck(r?.sources,`關係 ${r?.id}`);if(!['已查證事實','分析性解釋','待查證內容','典型流程示意'].includes(r?.status))errors.push(`關係 ${r?.id} 狀態無效。`);const named=['供應','客戶','合作','競爭','股權隸屬'].includes(r?.type)&&data.nodes.find(n=>n.id===r?.source)?.type==='企業'&&data.nodes.find(n=>n.id===r?.target)?.type==='企業';if(named&&r.status==='已查證事實'&&!r.sources?.length)errors.push(`具名企業關係 ${r.id} 需要可核對來源。`);if(r.note!=null&&typeof r.note!=='string')errors.push(`關係 ${r?.id} 備註須為文字。`);}return [...new Set(errors)];}
export function encode(data){return JSON.stringify(data,null,2)}
export function decode(text){const d=JSON.parse(text);const errors=validate(d);if(errors.length)throw new Error(errors.slice(0,12).join('\n'));return d;}
